#include "global.h"
#include "event_data.h"
#include "constants/flags.h"
#include "constants/vars.h"
#include "constants/opponents.h"
#include "topaze_journal.h"

// Topaze: JOURNAL data and logic. Objectives sorted in sections; the screen is in topaze_journal_screen.c.
// Entries come from src/data/topaze_journal.h (generated by docs/topaze/journal_gen.py).
#define JK_FLAG    0
#define JK_VAR     1
#define JK_TRAINER 2

struct TopazeJournalSection
{
    const u8 *name;
    u16 gate; // 0 = always visible, else the flag that unlocks the section
};

struct TopazeJournalEntry
{
    u8 section;
    u8 kind;
    u16 id;
    u16 val;
    const u8 *name;
    const u8 *hint;
};

#include "data/topaze_journal.h"

#define NUM_SECTIONS ARRAY_COUNT(sJournalSections)
#define NUM_ENTRIES  ARRAY_COUNT(sJournalEntries)

bool8 TopazeJournalEntryDone(u16 entry)
{
    const struct TopazeJournalEntry *e = &sJournalEntries[entry];

    switch (e->kind)
    {
    case JK_VAR:
        return VarGet(e->id) >= e->val;
    case JK_TRAINER:
        return FlagGet(TRAINER_FLAGS_START + e->id);
    default:
        return FlagGet(e->id);
    }
}

u8 TopazeJournalGetSections(u8 *out)
{
    u8 s, n = 0;

    for (s = 0; s < NUM_SECTIONS; s++)
    {
        if (sJournalSections[s].gate == 0 || FlagGet(sJournalSections[s].gate))
            out[n++] = s;
    }
    return n;
}

const u8 *TopazeJournalSectionName(u8 section)
{
    return sJournalSections[section].name;
}

void TopazeJournalCount(u8 section, u8 *done, u8 *total)
{
    u16 i;

    *done = 0;
    *total = 0;
    for (i = 0; i < NUM_ENTRIES; i++)
    {
        if (sJournalEntries[i].section != section)
            continue;
        (*total)++;
        if (TopazeJournalEntryDone(i))
            (*done)++;
    }
}

u8 TopazeJournalGetEntries(u8 section, u16 *out)
{
    u16 i;
    u8 n = 0;

    for (i = 0; i < NUM_ENTRIES && n < JOURNAL_MAX_ENTRIES; i++)
    {
        if (sJournalEntries[i].section == section)
            out[n++] = i;
    }
    return n;
}

const u8 *TopazeJournalEntryName(u16 entry)
{
    return sJournalEntries[entry].name;
}

const u8 *TopazeJournalEntryHint(u16 entry)
{
    return sJournalEntries[entry].hint;
}
